targets.expr:
sum by(le) (
  increase(
    vllm:request_prompt_tokens_bucket{
      model_name="$model_name",
      instance=~"$node",
      le!~"1.0|2.0|5.0|10.0|20.0|50.0|100.0|200.0|500.0|1000.0|2000.0", cluster="ai-cluster-1"}[$__rate_interval]
  )
)

sum by(le) (
  increase(
    vllm:request_generation_tokens_bucket{
      model_name="$model_name",
      instance=~"$node",
      le!~"1.0|2.0|5.0", cluster="ai-cluster-1"}[$__rate_interval]
  )
)

(
  rate(vllm:prefix_cache_hits_total{model_name="$model_name", instance=~"$node", cluster="ai-cluster-1"}[5m]) / clamp_min(rate(vllm:prefix_cache_queries_total{model_name="$model_name", instance=~"$node", cluster="ai-cluster-1"}[5m]), 1)
) + (
  1 - (
    rate(vllm:prefix_cache_hits_total{model_name="$model_name", instance=~"$node", cluster="ai-cluster-1"}[5m]) / clamp_min(rate(vllm:prefix_cache_queries_total{model_name="$model_name", instance=~"$node", cluster="ai-cluster-1"}[5m]), 1)
  )
) * (
  rate(vllm:external_prefix_cache_hits_total{model_name="$model_name", instance=~"$node", cluster="ai-cluster-1"}[5m]) / clamp_min(rate(vllm:external_prefix_cache_queries_total{model_name="$model_name", instance=~"$node", cluster="ai-cluster-1"}[5m]), 1)
)
